#include <iostream>
#include <string>
#include <algorithm>

int main() {
    int totalChars;
    std::cin >> totalChars;
    std::string str;
    std::cin >> str;
    for (auto &c : str) c = tolower(c);

    int maxLen = -1;
    int words = 0;
    int level = 0;
    int underlineCount = 0;

    for (int i = 0; i < totalChars; i++) {
        char c = str[i];
        if (c == '(') {
            level++;
            underlineCount = 0;
        } else if (c == ')') {
            if (level == 1 && underlineCount != 0) words++;
            level--;
            underlineCount = 0;
        } else if (c == '_') {
            if (level == 1 && underlineCount != 0) words++;
            underlineCount = 0;
        } else {
            underlineCount++;
        }
        if (level == 0) {
            maxLen = std::max(underlineCount, maxLen);
        }
    }
    std::cout << maxLen << " " << words << std::endl;
    return 0;
}
